char *build_user(const char *name, int age) {
  json_t *root = json_object();
  json_object_set_new(root, "name", json_string(name));
  json_object_set_new(root, "age", json_integer(age));

  json_t *tags = json_array();
  json_array_append_new(tags, json_string("member"));
  json_object_set_new(root, "tags", tags);

  json_t *meta = json_object();
  json_object_set_new(meta, "tags", tags);
  json_object_set_new(root, "meta", meta);

  char *out = json_dumps(root, JSON_COMPACT);
  json_decref(root);
  return out;
}
